INSERT INTO COMPANY (COM_ID, NAME, CITY) VALUES (1, 'RED', 'NY');
INSERT INTO ORDERS (ORDER_ID, COM_ID, SALES_ID, ORDER_DATE, AMOUNT) VALUES (1, 1, 2, '2023-01-01', 100);

